const text = $json.candidates?.[0]?.content?.parts?.[0]?.text;

if (!text) {
  throw new Error('Gemini returned no text content');
}

let result;
try {
  result = JSON.parse(text);
} catch (error) {
  throw new Error(`Invalid JSON from Gemini: ${text}`);
}

if (!result || !Array.isArray(result.queries)) {
  throw new Error(`Missing or invalid queries array in Gemini response: ${text}`);
}

if (result.queries.length === 0) {
  throw new Error('Queries array returned by Gemini is empty');
}

const source = $('Limit 1 Solution').item.json;

return [{
  json: {
    solutionId: source.id || source._id || '',
    solutionTitle: source.titleEn || source.titleTh || '',
    solutionUrl: source.url || source.link || '',
    solution: source,
    queries: result.queries
  }
}];

const input = $input.all();
const out = [];
const seen = new Set();

for (let i = 0; i < input.length; i++) {
  const results = input[i].json.results || [];
  const source = $('Split Out Queries').all()[i]?.json || {};
  for (const r of results) {
    if (!r.url) continue;
    const key = r.url.split('#')[0].replace(/\/$/, '');
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({
      json: {
        solution: source.solution,
        searchQuery: source.query,
        title: r.title || '',
        url: r.url,
        content: r.content || '',
        engine: r.engine || ''
      }
    });
  }
}
return out;

const text = $json.candidates?.[0]?.content?.parts?.[0]?.text || '';
let verdict;

try {
  verdict = JSON.parse(text);
} catch (e) {
  verdict = {
    relevant: false,
    score: 0,
    level: 'low',
    reason: 'Invalid JSON response from AI',
    matchedProblem: '',
    canAnswer: false
  };
}

const source = $('Top Candidates Filter').item.json;
const score = Number(verdict.score || 0);
const isRelevant = verdict.relevant === true && score >= 0.80;

return [{
  json: {
    ...source,
    relevant: isRelevant,
    matchScore: score,
    relevanceLevel: verdict.level || (score >= 0.80 ? 'high' : score >= 0.50 ? 'medium' : 'low'),
    reason: verdict.reason || '',
    matchedProblem: verdict.matchedProblem || '',
    canAnswer: verdict.canAnswer === true
  }
}];

const text = $json.candidates?.[0]?.content?.parts?.[0]?.text || '';

let draft = {
  answer: '',
  linkIncluded: false,
  linkReason: '',
  suggestedAnchor: ''
};

try {
  const parsed = JSON.parse(text);

  if (parsed && typeof parsed === 'object') {
    draft = {
      answer: parsed.answer || '',
      linkIncluded: parsed.linkIncluded === true,
      linkReason: parsed.linkReason || '',
      suggestedAnchor: parsed.suggestedAnchor || ''
    };
  }
} catch (e) {
  draft = {
    answer: text,
    linkIncluded: false,
    linkReason: 'Failed to parse AI response',
    suggestedAnchor: ''
  };
}


// Get source from relevance node
let source = {};

try {
  source = $('Relevant >= 0.80').item.json;
} catch (e) {
  try {
    source = $('Relevant >= 0.75').item.json;
  } catch (e) {
    source = {};
  }
}


// Extract platform
let platform = '';

try {
  platform = new URL(
    source.url || 'https://example.com'
  ).hostname;
} catch (e) {
  platform = source.url || '';
}


return [
  {
    json: {
      solutionId:
        source.solution?.id ||
        source.solution?._id ||
        '',

      solutionTitle:
        source.solution?.titleEn ||
        source.solution?.titleTh ||
        source.solution?.title ||
        '',

      solutionUrl:
        source.solution?.url ||
        source.solution?.link ||
        '',

      platform,

      postTitle:
        source.title || '',

      postUrl:
        source.url || '',

      searchQuery:
        source.searchQuery || '',

      matchedProblem:
        source.matchedProblem || '',

      matchScore:
        source.matchScore || 0,

      relevanceReason:
        source.reason || '',

      answer:
        draft.answer,

      linkIncluded:
        draft.linkIncluded,

      linkReason:
        draft.linkReason,

      suggestedAnchor:
        draft.suggestedAnchor,

      status: 'pending_review'
    }
  }
];

const items = $input.all();
if (items.length === 0) return [];

const groupedBySolution = {};

for (const item of items) {
  const sol = item.json.solution || {};
  const solKey = sol.id || sol.titleEn || sol.titleTh || 'default';

  if (!groupedBySolution[solKey]) {
    groupedBySolution[solKey] = [];
  }

  const solText = `${sol.titleEn || ''} ${sol.titleTh || ''} ${sol.descEn || ''} ${sol.descTh || ''}`.toLowerCase();
  const resText = `${item.json.title || ''} ${item.json.content || ''}`.toLowerCase();

  const tokenize = (text) => text.replace(/[^\w\s]/gi, ' ').split(/\s+/).filter(w => w.length > 2);
  const solTokens = new Set(tokenize(solText));
  const resTokens = tokenize(resText);

  if (solTokens.size === 0 || resTokens.length === 0) {
    item.json.similarityScore = 0;
    groupedBySolution[solKey].push(item);
    continue;
  }

  let matches = 0;
  const titleText = (item.json.title || '').toLowerCase();

  for (const token of resTokens) {
    if (solTokens.has(token)) {
      matches++;
    }
  }

  let titleBonus = 0;
  for (const token of solTokens) {
    if (titleText.includes(token)) {
      titleBonus += 0.15;
    }
  }

  const overlapScore = matches / Math.sqrt(solTokens.size * resTokens.length);
  const similarityScore = Math.min(1.0, overlapScore + titleBonus);

  item.json.similarityScore = parseFloat(similarityScore.toFixed(3));
  groupedBySolution[solKey].push(item);
}

const topCandidates = [];
for (const solKey in groupedBySolution) {
  const solGroup = groupedBySolution[solKey];
  solGroup.sort((a, b) => b.json.similarityScore - a.json.similarityScore);

  const top5 = solGroup.slice(0, 5);
  topCandidates.push(...top5);
}

return topCandidates;

const items = $input.all();
const out = [];

for (const item of items) {
  const queries = item.json.queries || [];
  const sol = item.json.solution || {};

  for (const q of queries) {
    if (!q || typeof q !== 'string') continue;
    out.push({
      json: {
        solution: sol,
        query: q
      }
    });
  }
}

return out;

